#!/usr/bin/env python3
"""Build and validate the built/food/environment industry analytics research corpus.

The compact source below is the maintainable authoring form.  JSONL files are the
machine-readable publication form.  Only Python's standard library is required.
"""

from __future__ import annotations

import json
from collections import Counter, defaultdict
from pathlib import Path


ROOT = Path(__file__).resolve().parent
RETRIEVED = "2026-08-25"


def source(sid, title, owner, url, sectors, supports, kind="official_standard_or_dataset"):
    number = sid.rsplit("-", 1)[-1]
    if any(token in owner for token in ["International Organization for Standardization", "Open Geospatial Consortium", "Codex", "GS1", "International Society of Automation", "IPCC"]):
        source_kind = "standard"
    elif any(token in title for token in ["Data", "Database", "FAOSTAT", "Inventory", "Index"]):
        source_kind = "official_statistics"
    elif any(token in owner for token in ["ASHRAE", "Valuation Standards Council", "Appraisal Foundation", "buildingSMART"]):
        source_kind = "professional_body"
    elif kind == "government_peer_reviewed_method":
        source_kind = "academic"
    else:
        source_kind = "regulator"
    return {
        "record_id": f"bfe.source.s{number}",
        "record_kind": "source_evidence",
        "edition": 1,
        "status": "verified",
        "source_id": sid,
        "title": title,
        "publisher": owner,
        "issuing_authority": owner,
        "url": url,
        "source_kind": source_kind,
        "primary_source": True,
        "accessed_at": RETRIEVED,
        "retrieved_on": RETRIEVED,
        "sector_tags": sectors,
        "supports": supports,
        "authority_scope": "The issuing body's own standard, regulatory program, official dataset, methodology or implementation surface.",
        "limitations": ["Authority is limited to the stated jurisdiction, standard scope, population, edition and method.", "A source supports the cited semantic or analytical obligation; it does not prove universal completeness or a product boundary."],
    }


