def system(system_id, name, sectors, capabilities, objects, shapes, hazards, evidence, extraction=None):
    number = system_id.rsplit("-", 1)[-1]
    subindustries = [f"built_food_environment.{s}" for s in sectors]
    return {
        "record_id": f"bfe.system.s{number}",
        "record_kind": "source_system_need",
        "edition": 1,
        "status": "sourced_candidate",
        "industry_id": "industry.built_food_environment",
        "subindustry_ids": subindustries,
        "source_class": name,
        "source_system_need_id": system_id,
        "source_system_class": name,
        "sector_tags": sectors,
        "required_capabilities": capabilities,
        "required_objects": objects,
        "objects": objects,
        "extraction_modes": extraction or ["versioned_snapshot", "incremental_change_or_event", "metadata_discovery", "bounded_historical_backfill"],
        "read_change_modes": extraction or ["versioned_snapshot", "incremental_change_or_event", "metadata_discovery", "bounded_historical_backfill"],
        "time_order_finality": ["event time is separate from record and ingestion time", "source timezone and clock quality are retained", "late and corrected records are representable", "snapshot cut and reopen/finality rule are declared"],
        "time_order_finality_contract": ["event_time_separate_from_record_time", "source_timezone_and_clock_quality", "late_and_corrected_records", "declared_snapshot_cut", "source_finality_or_reopen_rule"],
        "schema_semantics": ["stable object identities and hierarchy", "discoverable fields, code lists, units and constraints", "schema and semantic version", "null, delete, correction and redaction semantics"],
        "authority": "Read authority is source-object, tenant, jurisdiction and purpose scoped; analytical recommendations never imply write authority.",
        "authority_and_security": ["source_object_identity", "least_privilege_read", "row_field_or_spatial_scope_when_supported", "purpose_and_retention", "audit_receipt"],
        "required_data_shape_ids": shapes,
        "hazards": hazards,
        "known_hazards": hazards,
        "minimum_conformance_tests": ["enumerate_objects_and_schema", "stable_identity_across_extracts", "replay_same_cut_idempotently", "detect_delete_or_correction", "preserve_units_codes_and_quality_flags", "prove_denied_scope_is_not_readable"],
        "evidence_refs": evidence,
        "evidence_source_ids": evidence,
    }


