CASES = []


MODE_OPS = {
    "descriptive": ["operation.aggregate", "operation.normalize", "operation.reconcile"],
    "diagnostic": ["operation.segment", "operation.decompose", "operation.change_point", "operation.trace"],
    "root_cause": ["operation.causal_graph", "operation.counterfactual_compare", "operation.root_cause_rank"],
    "predictive": ["operation.fit", "operation.forecast", "operation.score_with_uncertainty"],
    "causal": ["operation.design_or_adjust", "operation.estimate_effect", "operation.sensitivity_analysis"],
    "simulation": ["operation.simulate", "operation.propagate_uncertainty", "operation.compare_scenarios"],
    "optimization": ["operation.formulate_constraints", "operation.optimize", "operation.robustness_check"],
    "reliability": ["operation.survival", "operation.hazard_estimation", "operation.renewal_model"],
    "spatial": ["operation.spatial_join", "operation.zonal_statistics", "operation.geostatistics"],
    "process": ["operation.process_mine", "operation.conformance_check", "operation.bottleneck_localize"],
    "risk": ["operation.identify_risk", "operation.quantify_risk", "operation.stress_test"],
    "compliance": ["operation.evaluate_rule", "operation.explain_exception", "operation.evidence_receipt"],
    "valuation": ["operation.define_basis", "operation.estimate_value", "operation.backtest"],
}


def add_case(domain, subindustry, slug, name, modes, question, action, methods, systems, shapes, evidence,
             unit, grain, actors, failures=None, assumptions=None, outputs=None):
    number = len(CASES) + 1
    ops = []
    for mode in modes:
        ops.extend(MODE_OPS.get(mode, []))
    CASES.append({
        "record_id": f"bfe.case.c{number:03d}",
        "record_kind": "analytical_case",
        "edition": 1,
        "status": "sourced_candidate",
        "industry_id": "industry.built_food_environment",
        "subindustry_ids": [f"built_food_environment.{domain}.{subindustry}"],
        "case_key": f"{domain}.{subindustry}.{slug}",
        "name": name,
        "analytical_modes": modes,
        "sovereign_question": question,
        "decision_or_action": action,
        "actors": actors,
        "unit_of_analysis": unit,
        "population": f"All in-scope {unit} for the declared enterprise, geography, operating regime and decision horizon; exclusions are explicit.",
        "grain": grain,
        "time_model": ["event/observation time is distinct from ingestion and correction time", "plans, forecasts, actuals and baselines are versioned", "biological/asset/project lifecycle and decision horizon are explicit", "late, censored and reopened states remain representable"],
        "source_system_refs": systems,
        "data_shape_refs": shapes,
        "data_type_refs": ["type.qualified_measurement", "type.interval_or_event_time", "type.identity", "type.uncertainty", "type.provenance"],
        "method_refs": methods,
        "operation_refs": list(dict.fromkeys(ops)),
        "inputs": [f"Qualified records conforming to {shape_id}" for shape_id in shapes] + ["Decision constraints, intervention authority, costs and forbidden actions"],
        "outputs": outputs or [f"Decision-grade {name.lower()} result at the declared grain", "diagnostic drivers or binding constraints with effect/importance and uncertainty", "recommended action or explicit no-action with feasibility and guardrails", "reproducible study, model/version and evidence receipt", "post-action verification plan"],
        "assumptions": assumptions or ["Stable identities and declared cross-system mappings", "Measurement, sampling and missingness mechanisms are characterized", "Method assumptions and transport limits are tested, not silently presumed", "No recommendation exceeds the actor's legal, safety, biological or contractual authority"],
        "invariants": ["Observed fact, sample result, estimate, forecast, scenario, plan and authorized action remain distinct truth kinds", "Units, population, denominator, grain, spatial support and time roles cannot be dropped", "Uncertainty and data-coverage limitations accompany every decision output", "Corrections supersede without erasing prior evidence", "A metric or dashboard tile alone cannot close this case"],
        "failure_modes": list(dict.fromkeys((failures or []) + ["selection or survivorship bias", "time leakage or post-treatment conditioning", "identity/grain mismatch", "unmodeled regime change", "optimization against a proxy without outcome verification"])),
        "evidence_refs": evidence,
        "llm_dependency": "prohibited_core",
        "limitations": ["Evidence supports the case structure and method obligations, not universal effectiveness in every enterprise.", "Local law, climate, biology, asset configuration, contracts and operating policy can change admissible inputs and actions.", "This candidate requires cross-industry method deduplication and independent domain review before adjudication."],
    })


