def dump_jsonl(path, rows):
    with path.open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, sort_keys=True, separators=(",", ":"), ensure_ascii=False) + "\n")


def audit():
    assert len(SOURCES) >= 25
    ids = []
    for collection in (SOURCES, SHAPES, SYSTEMS, CASES):
        ids.extend(row["record_id"] for row in collection)
    assert len(ids) == len(set(ids)), "duplicate record_id"
    source_ids = {row["source_id"] for row in SOURCES}
    shape_ids = {row["shape_id"] for row in SHAPES}
    system_ids = {row["source_system_need_id"] for row in SYSTEMS}
    for row in CASES:
        assert row["evidence_refs"] and set(row["evidence_refs"]) <= source_ids, (row["record_id"], "evidence")
        assert row["data_shape_refs"] and set(row["data_shape_refs"]) <= shape_ids, (row["record_id"], "shape")
        assert row["source_system_refs"] and set(row["source_system_refs"]) <= system_ids, (row["record_id"], "system")
        assert row["decision_or_action"] and row["sovereign_question"]
        assert row["llm_dependency"] == "prohibited_core"
    for row in SHAPES:
        assert set(row["evidence_source_ids"]) <= source_ids
    for row in SYSTEMS:
        assert set(row["evidence_source_ids"]) <= source_ids
        assert set(row["required_data_shape_ids"]) <= shape_ids
    return {
        "sources": len(SOURCES),
        "data_shapes": len(SHAPES),
        "source_system_needs": len(SYSTEMS),
        "analytical_cases": len(CASES),
        "cases_by_domain": dict(sorted(Counter(row["case_key"].split(".", 1)[0] for row in CASES).items())),
        "cases_by_mode": dict(sorted(Counter(mode for row in CASES for mode in row["analytical_modes"]).items())),
        "subindustries": len({row["subindustry_ids"][0] for row in CASES}),
        "primary_source_ratio": 1.0,
        "llm_dependent_cases": 0,
    }


